import { StatCard } from '@absoluteui/components/stat-card';

const host = document.createElement('div');
document.body.append(host);
const card = StatCard.create(host, {
  label: 'Revenue',
  value: 48200,
  previous: 40100,
  valueFormat: { style: 'currency', currency: 'USD', maximumFractionDigits: 0 },
  comparisonLabel: 'vs last month',
  trend: [31000, 35500, 38200, 40100, 48200],
});
host.dataset.delta = String(card.delta);

