import { StatCard } from '@absoluteui/components/stat-card';

const host = document.createElement('div');
document.body.append(host);
const card = StatCard.create(host, { label: 'Active users', value: null, busy: true });
export function showActiveUsers(count: number, previous: number): void {
  card.update({ busy: false, value: count, previous });
}
